SET NOCOUNT ON;
SET XACT_ABORT ON;
IF DB_NAME() IN('master','model','msdb','tempdb','DatabaseGym') THROW 51000,'Use la copia mejorada o una base de pruebas.',1;
IF OBJECT_ID('dbo.Usuario_Credencial','U') IS NULL OR OBJECT_ID('dbo.App_Auditoria','U') IS NULL THROW 51000,'Primero instale las migraciones anteriores.',1;
BEGIN TRANSACTION;
IF COL_LENGTH('dbo.Usuario_Credencial','DebeCambiarClave') IS NULL EXEC(N'ALTER TABLE dbo.Usuario_Credencial ADD DebeCambiarClave bit NOT NULL CONSTRAINT DF_Credencial_CambioInicial DEFAULT(0) WITH VALUES');
DECLARE @p int,@f int;
IF NOT EXISTS(SELECT 1 FROM dbo.Permiso WHERE Permiso=N'PuedeCrearUsuarios') INSERT dbo.Permiso(Nombre,Permiso) VALUES(N'Crear usuarios',N'PuedeCrearUsuarios');
IF NOT EXISTS(SELECT 1 FROM dbo.Permiso WHERE Permiso=N'PuedeEliminarSocios') INSERT dbo.Permiso(Nombre,Permiso) VALUES(N'Eliminar socios',N'PuedeEliminarSocios');
IF NOT EXISTS(SELECT 1 FROM dbo.Permiso WHERE Permiso=N'PuedeEliminarEntrenadores') INSERT dbo.Permiso(Nombre,Permiso) VALUES(N'Eliminar entrenadores',N'PuedeEliminarEntrenadores');
IF NOT EXISTS(SELECT 1 FROM dbo.Permiso WHERE Permiso=N'PuedeAccederANegocio') INSERT dbo.Permiso(Nombre,Permiso) VALUES(N'Operacion del gimnasio',N'PuedeAccederANegocio');
IF NOT EXISTS(SELECT 1 FROM dbo.Permiso WHERE Nombre=N'APP Administracion de cuentas' AND Permiso IS NULL) INSERT dbo.Permiso(Nombre,Permiso) VALUES(N'APP Administracion de cuentas',NULL);
IF NOT EXISTS(SELECT 1 FROM dbo.Permiso WHERE Nombre=N'APP Recepcion' AND Permiso IS NULL) INSERT dbo.Permiso(Nombre,Permiso) VALUES(N'APP Recepcion',NULL);
IF (SELECT COUNT(*) FROM dbo.Permiso WHERE Nombre=N'APP Administracion de cuentas' AND Permiso IS NULL)<>1 OR (SELECT COUNT(*) FROM dbo.Permiso WHERE Nombre=N'APP Recepcion' AND Permiso IS NULL)<>1 THROW 51000,'Hay familias de perfil duplicadas. Revise antes de continuar.',1;
SELECT @f=Id_Permiso FROM dbo.Permiso WHERE Nombre=N'APP Administracion de cuentas' AND Permiso IS NULL;
DELETE dbo.Permiso_Permiso WHERE id_permiso_padre=@f;
SELECT @p=MIN(Id_Permiso) FROM dbo.Permiso WHERE Permiso=N'PuedeCrearUsuarios';
INSERT dbo.Permiso_Permiso(id_permiso_padre,id_permiso_hijo) VALUES(@f,@p);
SELECT @f=Id_Permiso FROM dbo.Permiso WHERE Nombre=N'APP Recepcion' AND Permiso IS NULL;
DELETE dbo.Permiso_Permiso WHERE id_permiso_padre=@f;
SELECT @p=MIN(Id_Permiso) FROM dbo.Permiso WHERE Permiso=N'PuedeAccederANegocio';
INSERT dbo.Permiso_Permiso(id_permiso_padre,id_permiso_hijo) VALUES(@f,@p);
IF OBJECT_ID('dbo.App_CambioPerfil','U') IS NULL CREATE TABLE dbo.App_CambioPerfil(Id int IDENTITY PRIMARY KEY,Id_Usuario int NOT NULL,PermisosAnterioresXml nvarchar(max) NOT NULL,PerfilNuevo nvarchar(100) NOT NULL,OperadorWindows nvarchar(256) NOT NULL DEFAULT ORIGINAL_LOGIN(),FechaUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
COMMIT;
PRINT 'Perfiles preparados. No se reasigno ninguna cuenta.';
